use std::collections::{HashMap, HashSet};

struct Solution;

impl Solution {
    pub fn can_cross(stones: Vec<i32>) -> bool {
        let n = stones.len();
        let stone_positions: HashSet<i32> = stones.iter().cloned().collect();
        let last_stone = stones[n - 1];

        // dp map: key = stone position, value = set of jump sizes that can reach this stone
        let mut dp: HashMap<i32, HashSet<i32>> = HashMap::new();
        dp.insert(0, HashSet::from([0]));

        for &stone in &stones {
            if let Some(jumps) = dp.get(&stone) {
                for &k in jumps {
                    for next_jump in [k - 1, k, k + 1] {
                        if next_jump > 0 {
                            let next_pos = stone + next_jump;
                            if next_pos == last_stone {
                                return true;
                            }
                            if stone_positions.contains(&next_pos) {
                                dp.entry(next_pos).or_default().insert(next_jump);
                            }
                        }
                    }
                }
            }
        }

        false
    }
}

